package scanner

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/CreativeBeastDesign/pokkum/internal/ports"
)

// advisorySnapshotJSON is the offline toolchain advisory snapshot: real,
// published advisories for the Bun runtime and @sveltejs/kit, generated by
// scripts/snapshot-advisories from OSV.dev and GitHub's oven-sh/bun
// repository advisories. Never hand-edit it; regenerate it with
// `go run ./scripts/snapshot-advisories`.
//
// It is the only source of Bun runtime advisories even for an online scan:
// most Bun advisories are published as oven-sh/bun repository advisories,
// which OSV.dev does not carry under any package a version query can reach.
// For @sveltejs/kit it is the offline fallback; an online scan also queries
// OSV live and the two are de-duplicated by advisory ID.
//
//go:embed advisories.json
var advisorySnapshotJSON []byte

// AdvisorySnapshot is the on-disk shape of advisories.json. Exported only so
// scripts/snapshot-advisories writes exactly what this package loads.
type AdvisorySnapshot struct {
	// Snapshot is the UTC date (YYYY-MM-DD) the data was fetched. Advisories
	// published after it are invisible to an offline scan, so it is surfaced
	// in the offline scan's warnings.
	Snapshot   string             `json:"snapshot"`
	Sources    []string           `json:"sources"`
	Advisories []EmbeddedAdvisory `json:"advisories"`
}

// EmbeddedAdvisory is one advisory for one package, with every affected
// version range for that package.
type EmbeddedAdvisory struct {
	ID        string          `json:"id"`
	Aliases   []string        `json:"aliases,omitempty"`
	Package   string          `json:"package"`
	Severity  ports.Severity  `json:"severity"`
	Title     string          `json:"title"`
	URL       string          `json:"url"`
	Ranges    []AdvisoryRange `json:"ranges"`
	Published string          `json:"published,omitempty"`
}

// AdvisoryRange is one affected interval, in OSV's event vocabulary.
// Introduced "" or "0" means "from the first release". Fixed is exclusive,
// LastAffected inclusive; a range with neither has no fix yet.
type AdvisoryRange struct {
	Introduced   string `json:"introduced,omitempty"`
	Fixed        string `json:"fixed,omitempty"`
	LastAffected string `json:"last_affected,omitempty"`
}

// toolchainAdvisoryPackages are the packages the toolchain check matches.
// An entry for anything else in the snapshot would never be consulted, so
// ValidateSnapshot rejects it rather than letting it sit there unused.
var toolchainAdvisoryPackages = map[string]bool{"bun": true, "@sveltejs/kit": true}

// embeddedSnapshot is advisories.json, parsed and validated once at init. A
// malformed snapshot is a build-time defect in a file this repository
// generates, so it panics rather than letting the scanner run with no data.
var embeddedSnapshot = mustLoadSnapshot(advisorySnapshotJSON)

func mustLoadSnapshot(data []byte) AdvisorySnapshot {
	snap, err := ParseAdvisorySnapshot(data)
	if err != nil {
		panic(fmt.Sprintf("scanner: embedded advisories.json is invalid (regenerate with go run ./scripts/snapshot-advisories): %v", err))
	}
	return snap
}

// ParseAdvisorySnapshot decodes and validates a snapshot.
func ParseAdvisorySnapshot(data []byte) (AdvisorySnapshot, error) {
	var snap AdvisorySnapshot
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&snap); err != nil {
		return AdvisorySnapshot{}, fmt.Errorf("decoding advisory snapshot: %w", err)
	}
	if err := ValidateSnapshot(snap); err != nil {
		return AdvisorySnapshot{}, err
	}
	return snap, nil
}

// ValidateSnapshot rejects a snapshot the matcher could misread: an unknown
// package or severity, an advisory with no ID or no ranges, or a range that
// sets both Fixed and LastAffected.
func ValidateSnapshot(snap AdvisorySnapshot) error {
	if snap.Snapshot == "" {
		return fmt.Errorf("advisory snapshot has no snapshot date")
	}
	if len(snap.Advisories) == 0 {
		return fmt.Errorf("advisory snapshot contains no advisories")
	}
	seen := map[string]bool{}
	for _, adv := range snap.Advisories {
		key := adv.Package + "/" + adv.ID
		switch {
		case adv.ID == "":
			return fmt.Errorf("advisory for %q has no id", adv.Package)
		case !toolchainAdvisoryPackages[adv.Package]:
			return fmt.Errorf("advisory %s: package %q is not a toolchain package", adv.ID, adv.Package)
		case !adv.Severity.Valid():
			return fmt.Errorf("advisory %s: invalid severity %q", adv.ID, adv.Severity)
		case len(adv.Ranges) == 0:
			return fmt.Errorf("advisory %s: no affected ranges", adv.ID)
		case seen[key]:
			return fmt.Errorf("advisory %s listed twice for %s", adv.ID, adv.Package)
		}
		seen[key] = true
		for _, r := range adv.Ranges {
			if r.Fixed != "" && r.LastAffected != "" {
				return fmt.Errorf("advisory %s: range sets both fixed and last_affected", adv.ID)
			}
		}
	}
	return nil
}

// affects reports whether version v falls in any of a's ranges, and returns
// that range's fix ("" when the range has none).
//
// The lower bound only excludes v when introduced is provably newer than v.
// compareVersions resolves an unorderable pair to -1 (see its doc comment),
// so asking "is introduced > v" rather than "is v < introduced" keeps an
// unparseable version on the affected side, the fail-safe direction for a
// CVE gate. The upper bounds go through compareVersions the same way.
func (a EmbeddedAdvisory) affects(v string) (fixed string, ok bool) {
	v = cleanVersion(v)
	if v == "" {
		return "", false
	}
	for _, r := range a.Ranges {
		if intro := cleanVersion(r.Introduced); intro != "" && intro != "0" && compareVersions(intro, v) > 0 {
			continue
		}
		switch {
		case r.Fixed != "":
			if isVersionOlderThan(v, r.Fixed) {
				return r.Fixed, true
			}
		case r.LastAffected != "":
			if compareVersions(v, cleanVersion(r.LastAffected)) <= 0 {
				return "", true
			}
		default:
			return "", true
		}
	}
	return "", false
}

// vulnerability renders a matched advisory as a finding against version v.
func (a EmbeddedAdvisory) vulnerability(v, fixed string) ports.Vulnerability {
	return ports.Vulnerability{
		ID:           a.ID,
		Severity:     a.Severity,
		Package:      a.Package,
		Version:      v,
		FixedVersion: fixed,
		Title:        a.Title,
		Description:  strings.Join(a.Aliases, ", "),
		URL:          a.URL,
		Ecosystem:    "npm",
	}
}
